/* Banking Platform — an editorial product exhibit, with reference captures and local explanatory interactions. */
const BK_GUIDE='https://github.com/catalisaio/wpp.bb.catalisa.io/blob/master/docs/design/conta-app/guia/index.html';
const BK_SHOT_NOTES={
 'bank-mobile.png':'Aplicativo em aparelho · material de referência de 09/10/2026. Não é uma captura ao vivo.',
 'bank-desktop.jpg':'Protótipo do desktop do titular · guia de 29/09/2026 · dados de exemplo.',
 'bank-statement.jpg':'Protótipo do extrato no desktop · guia de 29/09/2026 · dados de exemplo.',
 'bank-console.jpg':'Protótipo do console / contas · guia de 29/09/2026 · dados de exemplo.',
 'bank-access.jpg':'Protótipo do console / pessoas e acessos · guia de 29/09/2026 · dados de exemplo.',
 'bank-analysis.jpg':'Protótipo do console / análise · guia de 29/09/2026 · dados de exemplo.'
};
window.SCREENSHOTS.filter(s=>s.product==='banking').forEach(s=>{if(BK_SHOT_NOTES[s.file])s.desc=BK_SHOT_NOTES[s.file]});
function bkShot(file,alt,cls='',eager=false){return `<button class="bk-shot ${cls}" data-gallery-file="${file}" data-gallery-product="banking" aria-label="Ampliar ${alt}"><img src="/assets/screens/${file}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'}><span class="bk-shot-open">Ver em detalhe ↗</span></button>`;}
function bkFoundation(){return `<svg class="bk-hero-foundation" viewBox="0 0 700 650" aria-hidden="true"><defs><linearGradient id="bk-plinth"><stop stop-color="#d9c8e5"/><stop offset="1" stop-color="#a684be"/></linearGradient><linearGradient id="bk-bridge"><stop stop-color="#f7bf8a"/><stop offset="1" stop-color="#d98e51"/></linearGradient></defs><circle cx="375" cy="283" r="231" fill="#e4d7eb"/><g fill="none" stroke="#c6b2d2" stroke-width=".8"><path d="M40 452L326 287L658 479L372 644Z"/><path d="M112 494L398 329M184 535L470 370M256 577L542 412M112 411L444 603M184 369L516 561M256 328L588 520" stroke-dasharray="2 8"/></g><path d="M110 448L325 324L579 471L364 595Z" fill="url(#bk-plinth)"/><path d="M110 448V469L364 616V595Z" fill="#b197c3"/><path d="M364 595L579 471V492L364 616Z" fill="#916ba9"/><g class="bk-bridge-piece"><path d="M169 421L191 408L440 552L418 565Z" fill="#ffd0a3"/><path d="M169 421V434L418 578V565Z" fill="url(#bk-bridge)"/><path d="M418 565L440 552V565L418 578Z" fill="#c47a43"/></g><circle class="bk-orbit-dot" cx="562" cy="157" r="22" fill="#efc46f"/><circle cx="562" cy="157" r="35" fill="none" stroke="#d3b993" stroke-width=".7"/><g stroke="#b59ac7" stroke-width=".8"><path d="M49 262H99M74 237V287M588 548H638M613 523V573"/></g></svg>`;}
function bkLayersArt(){return `<svg class="bk-layers-art" viewBox="0 0 620 530" role="img" aria-label="Três planos conectados: canais, capacidades e provedor da conta"><defs><linearGradient id="bk-layer-fill"><stop stop-color="#b493cf"/><stop offset="1" stop-color="#76518f"/></linearGradient></defs><g fill="none" stroke="#825a95" stroke-width="1"><path d="M123 189V355M310 80V246M497 189V355" stroke-dasharray="3 7"/><path class="bk-layer-route" d="M310 104V252L412 311V393" stroke="#edb57f" stroke-width="2" stroke-dasharray="3 12"/></g><g class="bk-layer-plane bk-plane-provider"><path d="M111 349L310 234L509 349L310 464Z" fill="#624474"/><path d="M111 349V366L310 481V464Z" fill="#4b325a"/><path d="M310 464L509 349V366L310 481Z" fill="#3f294d"/><path d="M245 338L310 300L375 338L310 376Z" fill="#9a78af"/><path d="M245 338V351L310 389V376Z" fill="#78578a"/><path d="M310 376L375 338V351L310 389Z" fill="#694779"/></g><g class="bk-layer-plane bk-plane-capabilities"><path d="M111 241L310 126L509 241L310 356Z" fill="url(#bk-layer-fill)"/><path d="M111 241V258L310 373V356Z" fill="#7b568f"/><path d="M310 356L509 241V258L310 373Z" fill="#5e3b74"/><g fill="#e8bc90"><path d="M213 218L248 198L283 218L248 238Z"/><path d="M283 258L318 238L353 258L318 278Z"/><path d="M353 218L388 198L423 218L388 238Z"/></g><g fill="none" stroke="#e4cfae" stroke-width="1"><path d="M248 218L318 258L388 218"/></g></g><g class="bk-layer-plane bk-plane-channels"><path d="M111 133L310 18L509 133L310 248Z" fill="#d4bfe3"/><path d="M111 133V150L310 265V248Z" fill="#ab8fc0"/><path d="M310 248L509 133V150L310 265Z" fill="#87639f"/><g stroke="#77528f" fill="none" stroke-width="1.3"><path d="M227 121L260 102L293 121L260 140Z"/><path d="M227 121V94L260 75L260 102M260 75L293 94V121"/><path d="M308 168L330 155V115L308 128ZM308 128L291 118L313 105L330 115"/><path d="M373 118L403 100V77L373 95ZM373 95L342 77L372 59L403 77"/></g></g><g fill="#bb99ce" font-family="monospace" font-size="9" letter-spacing="1.6"><text x="49" y="169">01</text><text x="49" y="278">02</text><text x="49" y="386">03</text></g></svg>`;}
const BK_CHANNELS=[
 {id:'app',label:'No aplicativo',role:'O TITULAR / APP',title:'O banco acompanha<br>o ritmo da pessoa.',copy:'Saldo, extrato, Pix e acompanhamento no celular. A experiência mostra o próximo passo e o que ainda precisa de confirmação.',details:[['Entrar com contexto','O vínculo do aparelho participa do acesso.'],['Entender a posição','O que está disponível e o que está reservado ficam separados.'],['Saber o que aconteceu','Os estados da operação ajudam a pessoa a continuar.']]},
 {id:'desktop',label:'No desktop',role:'O TITULAR / DESKTOP',title:'Mais espaço para<br>olhar a conta.',copy:'Uma experiência desenhada para leitura, consulta e preparação. O desenho do desktop mantém o aparelho na jornada de autorização.',details:[['Ler o extrato','Lançamentos e comprovantes em uma área de trabalho ampla.'],['Preparar uma operação','A pessoa confere as informações antes de continuar.'],['Autorizar pelo aparelho','O protótipo separa a preparação no computador da confirmação no celular.']]},
 {id:'console',label:'Na operação',role:'A EQUIPE / CONSOLE',title:'Quem opera precisa<br>enxergar o contexto.',copy:'Contas e bloqueios têm interfaces implementadas no console. O guia também apresenta o desenho de pedidos, acessos e análise.',details:[['Acompanhar contas','Uma visão de operação, com posição e estado.'],['Entender reservas','Valores, motivos e referências ajudam a explicar o disponível.'],['Separar responsabilidades','O console apresenta o trabalho e as respostas da base.']]}
];
function bkChannelPanel(c,i){return `<section class="bk-channel-panel bk-channel-${c.id}" id="bk-panel-${c.id}" role="tabpanel" aria-labelledby="bk-tab-${c.id}" ${i?'hidden':''}><div class="bk-channel-copy"><span class="bk-eyebrow">${c.role}</span><h3>${c.title}</h3><p>${c.copy}</p><dl>${c.details.map(([title,desc])=>`<div><dt>${title}</dt><dd>${desc}</dd></div>`).join('')}</dl><span class="bk-capture-note">${c.id==='app'?'App em aparelho · referência de 09/10/2026':c.id==='desktop'?'Desktop · protótipo do guia de 29/09/2026':'Console implementado · staging · guia de 29/09/2026'}</span></div><div class="bk-channel-visual">${c.id==='app'?`<span class="bk-channel-ring" aria-hidden="true"></span>${bkShot('bank-mobile.png','aplicativo Banking no aparelho','bk-channel-phone')}<span class="bk-channel-side">UM APARELHO.<br>UM PONTO DE CONTINUIDADE.</span>`:c.id==='desktop'?`<div class="bk-display-label"><span>CONTA DO TITULAR / INÍCIO</span><span>Ampliar ↗</span></div>${bkShot('bank-desktop.jpg','conta do titular no desktop','bk-channel-desktop')}<div class="bk-extract-preview">${bkShot('bank-statement.jpg','extrato no desktop')}<span>Uma leitura organizada<br>dos movimentos da conta.</span></div>`:`<div class="bk-display-label"><span>CONSOLE / CONTAS</span><span>Ampliar ↗</span></div>${bkShot('bank-live-accounts.jpg','console implementado de contas','bk-channel-console')}<span class="bk-console-caption">A captura mantém o contexto de teste visível. Não é uma operação ao vivo.</span>`}</div></section>`;}
const BK_LAYER_COPY={channels:['A experiência apresenta.','App, desktop e console têm papéis diferentes. O canal organiza a interação e mostra o estado recebido da base.'],capabilities:['Cada capacidade responde pelo seu trabalho.','Banking organiza a entrada do aplicativo. Identidade, regras de acesso e outras capacidades entram conforme a composição.'],provider:['A movimentação tem um responsável.','O BaaS faz a ponte com o provedor da conta. Produto, configuração e validação da operação precisam ser definidos para cada implementação.']};
const BK_BALANCES={free:{bank:300,reserved:0,usable:300,title:'Uma posição, sem reserva estruturada.',copy:'Neste exemplo, o valor informado pelo banco está disponível para movimentação.',label:'Pode movimentar',status:'Leitura disponível'},reserved:{bank:300,reserved:200,usable:100,title:'Uma parte do valor tem outro destino.',copy:'A reserva estruturada de R$ 200,00 reduz o que pode ser movimentado para R$ 100,00.',label:'Pode movimentar',status:'Reserva identificada'},checking:{bank:300,reserved:200,usable:null,title:'Quando os números pedem uma conferência.',copy:'O exemplo interrompe a leitura do valor movimentável até esclarecer a divergência. Uma resposta incerta continua identificada como incerta.',label:'Pode movimentar',status:'Em conferência'}};
function bkBalance(){return `<div class="bk-balance-example" id="bk-balance-example" data-state="reserved"><div class="bk-example-top"><span>EXEMPLO ILUSTRATIVO / SEM MOVIMENTAÇÃO REAL</span><span id="bk-balance-state">Reserva identificada</span></div><div class="bk-balance-values"><div><span>Informado pelo banco</span><strong id="bk-bank-value">R$ 300,00</strong></div><div><span>Reserva estruturada</span><strong id="bk-reserved-value">R$ 200,00</strong></div><div><span>Pode movimentar</span><strong id="bk-usable-value">R$ 100,00</strong></div></div><div class="bk-balance-rail" role="img" aria-label="De 300 reais informados pelo banco, 200 estão reservados e 100 podem ser movimentados"><span id="bk-reserved-part" style="width:66.6667%"></span><span id="bk-usable-part" style="width:33.3333%"></span></div><div class="bk-rail-key"><span>● Reservado</span><span>● Movimentável</span></div><div class="bk-balance-explanation" role="status"><h3 id="bk-balance-title">Uma parte do valor tem outro destino.</h3><p id="bk-balance-copy">A reserva estruturada de R$ 200,00 reduz o que pode ser movimentado para R$ 100,00.</p></div></div>`;}
const BK_TOUR=[
 ['O pedido começa no canal.','A pessoa prepara uma operação e confere o que pretende fazer.','Preparado no desktop','Aguardando confirmação','O console ainda não deve tratar intenção como movimentação.'],
 ['A confirmação ganha contexto.','A experiência de autorização é definida pela base, conforme a configuração da jornada.','Confirmar no aparelho','Contexto da operação','O canal apresenta o que precisa ser confirmado.'],
 ['A base responde pelo próximo passo.','A operação depende da autorização e do resultado dos serviços responsáveis.','Resposta em consulta','Aguardando resultado','Uma espera não deve aparecer como sucesso.'],
 ['A resposta chega a quem precisa.','O titular acompanha o estado e a equipe tem uma referência para continuar o atendimento.','Estado acompanhado','Contexto compartilhado','Cliente e operação continuam a partir da mesma referência.']
];
function bkJourney(){return `<section class="bk-tour wrap" aria-label="Percurso explicativo de uma operação"><div class="bk-tour-heading"><span class="bk-eyebrow">ACOMPANHE UMA OPERAÇÃO POR DENTRO</span><h2>Um pedido.<br><em>Dois lados da experiência.</em></h2><p>Percorra um exemplo para entender como a experiência do titular se conecta ao trabalho da operação.</p></div><div class="bk-tour-layout"><div class="bk-tour-story"><div class="bk-tour-steps" role="group" aria-label="Momentos do percurso">${BK_TOUR.map((_,i)=>`<button data-bk-tour="${i}" aria-pressed="${!i}">0${i+1}</button>`).join('')}</div><h3 id="bk-tour-title">${BK_TOUR[0][0]}</h3><p id="bk-tour-copy">${BK_TOUR[0][1]}</p><button class="text-link" data-bk-tour-next>Próximo momento →</button><small>Demonstração explicativa. Nenhum pedido, autorização ou movimentação é realizado.</small></div><div class="bk-tour-scene" id="bk-tour-scene" data-step="0"><div class="bk-tour-client"><span>O TITULAR</span><div class="bk-tour-phone-top"></div><div class="bk-tour-glyph">↗</div><strong id="bk-tour-client-state">${BK_TOUR[0][2]}</strong><p>Uma operação.<br>Um próximo passo claro.</p><div class="bk-tour-phone-line"></div><div class="bk-tour-phone-line short"></div></div><div class="bk-tour-link" aria-hidden="true"><i></i><i></i><i></i></div><div class="bk-tour-console"><span>A OPERAÇÃO</span><div class="bk-tour-console-top"><i></i><i></i><i></i></div><small>REFERÊNCIA / EXEMPLO 024</small><strong id="bk-tour-operation-state">${BK_TOUR[0][3]}</strong><div class="bk-tour-status-line"><i></i><span>Contexto do pedido</span></div><p id="bk-tour-operation-copy">${BK_TOUR[0][4]}</p></div></div></div></section>`;}
function bkPage(p,blocks){const modules=[['banking','A entrada do aplicativo','Conecta o canal às capacidades responsáveis.'],['baas','A relação com a conta','Organiza a integração com o provedor bancário.'],['iam','Identidade e acesso','Delimita pessoas, organizações e permissões.'],['biometrics','Verificação de identidade','Pode compor as jornadas de verificação previstas.'],['banking-product-portfolio','O catálogo do produto','Organiza produtos e suas versões.'],['feature-flags','Evolução por etapas','Controla a exposição das funcionalidades configuradas.'],['audit-trail','Um histórico com referência','Registra os eventos publicados pelas capacidades.']];return `<div class="bk-page" id="bk-page"><section class="bk-hero"><div class="wrap bk-hero-inner"><div class="bk-hero-copy"><span class="bk-eyebrow">CATALISA / BANKING PLATFORM</span><h1>Uma conta.<br>Várias formas<br>de <em>operar.</em></h1><p>O titular acompanha. O aplicativo conecta.<br>A equipe opera com contexto.</p><a href="#bk-experiencias" class="text-link">Explore os pontos de vista ↓</a><div class="bk-hero-index"><span>01 / APP</span><span>02 / DESKTOP</span><span>03 / CONSOLE</span></div></div><div class="bk-hero-art">${bkFoundation()}<div class="bk-hero-desktop"><span class="bk-window-bar"><i></i><i></i><i></i><span>CONTA DO TITULAR</span></span>${bkShot('bank-desktop.jpg','desktop do Banking Platform','',true)}</div><div class="bk-hero-phone">${bkShot('bank-mobile.png','aplicativo Banking','',true)}</div><span class="bk-hero-caption">Uma base compartilhada.<br>Experiências com trabalhos próprios.</span></div><div class="bk-hero-foot"><span>Uma composição construída sobre a Catalisa.</span><button data-bk-motion aria-pressed="false">Ⅱ Pausar movimento</button></div></div></section><section class="bk-premise wrap"><span class="bk-eyebrow">A EXPERIÊNCIA CONTINUA ALÉM DA TELA</span><div><h2>O banco aparece em canais.<br><em>O contexto atravessa todos.</em></h2><p>Uma conta digital precisa fazer sentido para quem usa e para quem cuida da operação. Banking aproxima essas experiências, com responsabilidades distribuídas na base.</p></div><nav class="bk-section-index" aria-label="Nesta página"><a href="#bk-experiencias">As interfaces <span>01</span></a><a href="#bk-base">A base <span>02</span></a><a href="#bk-posicao">A posição da conta <span>03</span></a><a href="#bk-operacao">A operação <span>04</span></a></nav></section><section class="bk-experiences" id="bk-experiencias"><div class="wrap"><div class="bk-section-heading"><span class="bk-eyebrow">01 / TRÊS PONTOS DE VISTA</span><h2>O mesmo fundamento.<br><em>Trabalhos diferentes.</em></h2><p>Troque o contexto para explorar<br>como cada interface participa.</p></div><div class="bk-channel-tabs" role="tablist" aria-label="Experiências Banking">${BK_CHANNELS.map((c,i)=>`<button role="tab" id="bk-tab-${c.id}" data-bk-channel="${c.id}" aria-controls="bk-panel-${c.id}" aria-selected="${!i}" tabindex="${i?-1:0}"><span>0${i+1}</span>${c.label}<i>↗</i></button>`).join('')}</div>${BK_CHANNELS.map(bkChannelPanel).join('')}</div></section><section class="bk-foundation" id="bk-base" data-layer="channels"><div class="wrap bk-foundation-inner"><div class="bk-foundation-copy"><span class="bk-eyebrow">02 / A BASE POR TRÁS DA EXPERIÊNCIA</span><h2>Entre tocar<br>e acontecer,<br>existe <em>uma base.</em></h2><p>O canal, a capacidade e o provedor têm papéis próprios. Essa separação ajuda a evoluir a experiência com mais clareza sobre quem responde por cada trabalho.</p><div class="bk-layer-options" role="group" aria-label="Explore as responsabilidades"><button data-bk-layer="channels" aria-pressed="true">01 <span>Canais</span>↗</button><button data-bk-layer="capabilities" aria-pressed="false">02 <span>Capacidades</span>↗</button><button data-bk-layer="provider" aria-pressed="false">03 <span>Provedor da conta</span>↗</button></div></div><div class="bk-foundation-visual">${bkLayersArt()}<div class="bk-layer-detail" role="status"><h3 id="bk-layer-title">${BK_LAYER_COPY.channels[0]}</h3><p id="bk-layer-copy">${BK_LAYER_COPY.channels[1]}</p></div></div><div class="bk-responsibility-note"><span>TRÊS NOMES. TRÊS RESPONSABILIDADES.</span><p><strong>Banking</strong> recebe o aplicativo. <strong>BaaS</strong> integra a conta e o provedor. <strong>Banking Product Portfolio</strong> organiza o catálogo de produtos.</p></div></div></section>${bkJourney()}<section class="bk-position wrap" id="bk-posicao"><div class="bk-position-copy"><span class="bk-eyebrow">03 / UMA CONTA, COM CONTEXTO</span><h2>Ter um saldo.<br>Entender o que<br><em>pode usar.</em></h2><p>Uma reserva muda a leitura da conta. Explicar o disponível ajuda o titular a decidir o próximo passo e a equipe a responder com clareza.</p><div class="bk-balance-options" role="group" aria-label="Escolha uma situação da conta"><button data-bk-balance="free" aria-pressed="false">Sem reserva</button><button data-bk-balance="reserved" aria-pressed="true">Com reserva</button><button data-bk-balance="checking" aria-pressed="false">Em conferência</button></div><small>Uma leitura simplificada do exemplo de bloqueio estruturado do guia. Não soma novamente bloqueios já descontados pelo provedor.</small></div>${bkBalance()}</section><section class="bk-operation" id="bk-operacao"><div class="wrap"><div class="bk-operation-heading"><div><span class="bk-eyebrow">04 / O TRABALHO DE QUEM OPERA</span><h2>Por trás da conta,<br><em>há uma operação.</em></h2></div><p>O console aproxima posição, motivo e histórico.<br>Quem atende encontra uma explicação.<br>Quem opera encontra o contexto.</p></div><div class="bk-console-exhibit"><div class="bk-console-label"><span>CONSOLE IMPLEMENTADO / BLOQUEIOS</span><span>STAGING · GUIA DE 29/09/2026</span></div>${bkShot('bank-live-holds.jpg','bloqueios no console implementado','bk-console-main')}<div class="bk-console-annotation"><span>OLHAR PARA ALÉM DO VALOR</span><p>Quanto está reservado.<br>Por qual motivo.<br>Qual referência acompanha o bloqueio.</p><strong>Uma posição que<br>pode ser explicada.</strong></div></div><div class="bk-console-more"><div><span class="bk-eyebrow">O DESENHO DA OPERAÇÃO</span><p>Outras áreas do console aparecem no protótipo do guia. Abra as capturas para explorar o desenho.</p></div>${[['bank-console.jpg','Contas no protótipo'],['bank-access.jpg','Pessoas e acessos'],['bank-analysis.jpg','Análise e acompanhamento']].map(([file,title])=>`<figure>${bkShot(file,title)}<figcaption>${title}<span>Protótipo / guia de 29/09/2026</span></figcaption></figure>`).join('')}</div></div></section><section class="bk-film wrap"><div><span class="bk-eyebrow">UM PERCURSO PELAS INTERFACES</span><h2>Veja a composição<br><em>ganhar espaço.</em></h2><p>Uma montagem visual das capturas de referência. Para ler os detalhes, abra as imagens na galeria.</p><small>Montagem de materiais do produto.<br>Não é uma gravação de operação bancária.</small></div><video controls playsinline preload="none" poster="/assets/screens/bank-desktop.jpg" aria-label="Montagem visual de interfaces do Banking Platform"><source src="/assets/media/banking-reel.mp4" type="video/mp4">Seu navegador não reproduz o vídeo. Explore as capturas acima.</video></section><section class="bk-capabilities wrap"><div class="bk-capabilities-heading"><span class="bk-eyebrow">CAPACIDADES COM RESPONSABILIDADE</span><h2>O produto encontra<br><em>as suas peças.</em></h2><p>Uma composição pode reunir estas capacidades conforme o escopo. Explore a função e o estágio de cada uma.</p></div><div class="bk-capability-list">${modules.map(([slug,title,copy],i)=>{const b=blocks.find(x=>x.slug===slug);return `<a href="/capacidades/${slug}/"><span>0${i+1}</span><div><small>${b?.name||slug}</small><h3>${title}</h3><p>${copy}</p></div><span class="bk-capability-status">${b?.status||'Consultar catálogo'}</span><i>↗</i></a>`}).join('')}</div></section><section class="bk-credit-connection"><div class="wrap"><div class="bk-credit-orbit" aria-hidden="true"><span></span><span></span><i>↗</i></div><div><span class="bk-eyebrow">A CONTA ENCONTRA OUTRAS JORNADAS</span><h2>O movimento da conta<br>pode fazer parte de<br><em>um produto maior.</em></h2><p>O guia explora uma antecipação ligada à conta: proposta, aceite e acompanhamento. A composição de crédito traz outro ponto de vista para essa continuidade.</p><a href="/ecossistema/credit/" class="text-link">Explore Credit Platform ↗</a></div></div></section><section class="bk-scope wrap"><div><span class="bk-eyebrow">REFERÊNCIAS E ESTÁGIO</span><h2>Uma visão completa.<br><em>Com contexto de origem.</em></h2><p>Os materiais mostram a direção do produto e partes implementadas. A disponibilidade de cada jornada depende do seu escopo e das integrações validadas.</p><a href="${BK_GUIDE}" target="_blank" rel="noopener" class="text-link">Consulte o guia completo ↗</a></div><div class="bk-scope-ledger"><div><span>Aplicativo</span><p>Captura em aparelho, com referência de 09/10/2026. A implementação e as jornadas evoluem conforme o material técnico.</p></div><div><span>Desktop</span><p>Protótipo do titular no guia. A imagem descreve o desenho da experiência.</p></div><div><span>Console</span><p>Contas e bloqueios aparecem em capturas de staging implementado. Outras áreas aqui exibidas são protótipos.</p></div><div><span>Integração bancária</span><p>O catálogo distingue estágios Alpha e Beta. Tela ou teste simulado não confirma homologação de uma integração real.</p></div></div></section><section class="bk-closing wrap"><span class="bk-eyebrow">UMA BASE. PRÓXIMAS POSSIBILIDADES.</span><h2>O próximo produto<br>começa nas <em>conexões.</em></h2><div><a href="/contato/" class="text-link">Converse com a Catalisa ↗</a><a href="/arquitetura/" class="text-link">Explore a arquitetura ↗</a></div></section></div>`;}
const bkPreviousProduct=cProduct;cProduct=function(p,blocks){return p.slug==='banking'?bkPage(p,blocks):bkPreviousProduct(p,blocks)};
function bkBind(){const page=document.getElementById('bk-page');if(!page)return;const tabs=[...page.querySelectorAll('[data-bk-channel]')];function selectChannel(id,focus=false){tabs.forEach(t=>{const active=t.dataset.bkChannel===id;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;if(active&&focus)t.focus({preventScroll:true});});}tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectChannel(t.dataset.bkChannel));t.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectChannel(tabs[n].dataset.bkChannel,true);});});page.querySelector('[data-bk-motion]').addEventListener('click',e=>{const paused=page.classList.toggle('bk-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▷ Retomar movimento':'Ⅱ Pausar movimento';});page.querySelectorAll('[data-bk-layer]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.bkLayer;document.getElementById('bk-base').dataset.layer=key;page.querySelectorAll('[data-bk-layer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('bk-layer-title').textContent=BK_LAYER_COPY[key][0];document.getElementById('bk-layer-copy').textContent=BK_LAYER_COPY[key][1];}));let tourIndex=0;const showTour=i=>{tourIndex=i;const t=BK_TOUR[i];page.querySelectorAll('[data-bk-tour]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.bkTour)===i)));document.getElementById('bk-tour-scene').dataset.step=String(i);['title','copy','client-state','operation-state','operation-copy'].forEach((key,j)=>document.getElementById('bk-tour-'+key).textContent=t[j]);page.querySelector('[data-bk-tour-next]').textContent=i===3?'Recomeçar percurso ↺':'Próximo momento →';};page.querySelectorAll('[data-bk-tour]').forEach(b=>b.addEventListener('click',()=>showTour(Number(b.dataset.bkTour))));page.querySelector('[data-bk-tour-next]').addEventListener('click',()=>showTour((tourIndex+1)%4));const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});page.querySelectorAll('[data-bk-balance]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.bkBalance,s=BK_BALANCES[key];page.querySelectorAll('[data-bk-balance]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('bk-balance-example').dataset.state=key;document.getElementById('bk-bank-value').textContent=money(s.bank);document.getElementById('bk-reserved-value').textContent=money(s.reserved);document.getElementById('bk-usable-value').textContent=s.usable===null?'Em conferência':money(s.usable);document.getElementById('bk-balance-state').textContent=s.status;document.getElementById('bk-balance-title').textContent=s.title;document.getElementById('bk-balance-copy').textContent=s.copy;document.getElementById('bk-reserved-part').style.width=(s.reserved/s.bank*100)+'%';document.getElementById('bk-usable-part').style.width=((s.bank-s.reserved)/s.bank*100)+'%';page.querySelector('.bk-balance-rail').setAttribute('aria-label',s.usable===null?'O valor movimentável está em conferência.':`${money(s.bank)} informados pelo banco, ${money(s.reserved)} de reserva estruturada e ${money(s.usable)} movimentáveis.`);}));}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',bkBind);
